/**
 * Design: Soft Sovereignty. This screen intentionally consumes catalogs and practice
 * metadata; new practices, flows, symbolic supports, and packs do not require UI rewrites.
 */
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import {
  ArrowLeft, ArrowRight, Bolt, Check, ChevronRight, Clock3, Compass, Flower2,
  Heart, HeartHandshake, Home as HomeIcon, Leaf, Pause, Play, RotateCcw, Settings2,
  ShieldCheck, Sparkles, SunMedium, X,
} from "lucide-react";
import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { filterSavedPractices } from "@/lib/libraryFilters";
import { PracticeHistoryTools } from "@/components/PracticeHistoryTools";
import { dailyAffirmations, energyHygieneMoments, getFlow, practiceStyleOptions, roseRays, supportFlows, type EnergyHygieneMoment, type RoseRayId } from "@/data/catalog";
import { activeRituals, centralizedPracticeLibrary as practices, findCanonicalRitual, findPracticeInCentralizedLibrary } from "@/data/canonicalRituals";
import { type FlowCategory, type Location, type Practice, type PracticeStyle } from "@/data/practices";
import { recommendPractice, recommendationReason, type PracticeQuery } from "@/lib/recommendPractice";
import { selectLiveSafetyAwarePractice } from "@/lib/liveSafetySelection";
import type { SafetyHandoff } from "@/lib/safetySelectionEngine";
import {
  clearDailyHygieneReminder, clearSevenDayCommitment, completeDailyHygieneForToday, createDailyHygieneReminder,
  createSevenDayCommitment, dismissDailyHygieneReminderForToday, getDailyHygienePlanProgress, hasCompletedOnboarding,
  isDailyHygieneReminderDue, loadDailyHygieneReminder, loadPreferences, loadSevenDayCommitment,
  remainingCommitmentDays, remainingDailyHygieneReminderDays, reorderEnergyHygieneShortcuts, saveDailyHygieneReminder, saveOnboardingCompleted, savePreferences,
  saveSevenDayCommitment, setDailyHygieneNoteForToday, setDailyHygieneReflection, type DailyHygieneReminder, type EnergyHygieneShortcutId, type SevenDayCommitment,
  type StoredPracticeStyle, type StoredTextSize,
} from "@/lib/localPersistence";
import type { PremiumOfferKey } from "../../../server/payments/products";

type View = "onboarding" | "home" | "intake" | "hygiene-choice" | "hygiene-restore" | "hygiene-daily" | "daily-ritual-picker" | "loading" | "recommendation" | "practice" | "daily-note" | "complete" | "daily-reflection" | "safety" | "settings" | "library" | "paywall";
type DisplayPathway = ReturnType<typeof getFlow> & { icon: typeof SunMedium; asset?: string };

const ASSETS = {
  logo: "/manus-storage/energetic-safeguard-mark_101130ee.png",
  roseField: "/manus-storage/quiet-rose-field_ce3f4800.jpg",
  boundary: "/manus-storage/golden-boundary-card_f0d9b21d.jpg",
  arrival: "/manus-storage/emerald-arrival-card_e70e9110.jpg",
};

const flowIcons: Record<string, typeof SunMedium> = { sun: SunMedium, shield: ShieldCheck, compass: Compass, leaf: Leaf, heart: HeartHandshake, bolt: Bolt };
const adjustmentOptions = [["avoid-breath", "Avoid breath-focused practices"], ["avoid-visualization", "Avoid visualization"], ["minimal-movement", "Keep movement minimal"], ["keep-eyes-open", "Keep eyes open"], ["discreet", "Keep this discreet"]] as const;
const makeDefaultQuery = (pathway: FlowCategory, style: PracticeQuery["style"]): PracticeQuery => ({ pathway, situation: "", intensity: 5, energy: "steady", availableMinutes: 3, location: "anywhere", style, adjustments: [], enabledContentPackIds: ["foundation"] });

function RoseMark({ compact = false }: { compact?: boolean }) { return <img src={ASSETS.logo} className={compact ? "rose-mark rose-mark--compact" : "rose-mark"} alt="The Energetic Safeguard rose compass" />; }
function AppHeader({ onHome, onSettings }: { onHome: () => void; onSettings: () => void }) { return <header className="app-header"><button className="wordmark" onClick={onHome} aria-label="Return to home"><RoseMark compact /><span><b>Energetic</b> Safeguard</span></button><button className="icon-button" onClick={onSettings} aria-label="Open settings"><Settings2 size={20} /></button></header>; }
function IntakeProgress({ step }: { step: number }) { return <div className="progress-dots" aria-label={`Question ${step + 1} of 3`}><i className={step >= 0 ? "active" : ""} /><i className={step >= 1 ? "active" : ""} /><i className={step >= 2 ? "active" : ""} /></div>; }
function EnergyHygieneChoice({ onHome, onSettings, onChoose }: { onHome: () => void; onSettings: () => void; onChoose: (moment: EnergyHygieneMoment) => void }) { return <main className="flow-screen"><AppHeader onHome={onHome} onSettings={onSettings} /><div className="flow-topline"><button className="back-button" onClick={onHome}><ArrowLeft size={18} /> Back</button><span>ENERGY HYGIENE</span></div><section className="settings-card energy-hygiene-card"><span className="energy-hygiene-mark"><Leaf size={25} /></span><p className="eyebrow">A SMALL RETURN TO YOURSELF</p><h1>What kind of energy care would support you now?</h1><p>Choose a focused practice for this moment. You can return to either option whenever it feels useful.</p><div className="energy-hygiene-options">{energyHygieneMoments.map((moment) => <button key={moment.id} className="energy-hygiene-option" onClick={() => onChoose(moment)}><span><b>{moment.label}</b><small>{moment.description}</small></span><i><ArrowRight size={17} /></i></button>)}</div><p className="energy-hygiene-note">These are general wellness supports. You decide what feels useful; nothing needs to be forced.</p></section></main>; }
function EnergyHygieneMomentScreen({ moment, onBack, onHome, onSettings, onBegin, isShortcut, onToggleShortcut, reminderActive, onToggleReminder, dailySelectedPractice, onChoosePlanRitual }: { moment: EnergyHygieneMoment; onBack: () => void; onHome: () => void; onSettings: () => void; onBegin: () => void; isShortcut: boolean; onToggleShortcut: () => void; reminderActive: boolean; onToggleReminder: () => void; dailySelectedPractice?: Practice | null; onChoosePlanRitual: () => void }) { const practice = dailySelectedPractice ?? findPracticeInCentralizedLibrary(moment.suggestedPracticeId); return <main className="flow-screen"><AppHeader onHome={onHome} onSettings={onSettings} /><div className="flow-topline"><button className="back-button" onClick={onBack}><ArrowLeft size={18} /> Energy hygiene</button><span>{moment.id === "after-interaction" ? "AFTER AN INTERACTION" : "DAILY RHYTHM"}</span></div><section className="settings-card energy-hygiene-card energy-hygiene-card--detail"><span className="energy-hygiene-mark"><Leaf size={25} /></span><p className="eyebrow">{moment.label}</p><h1>{moment.heading}</h1><p>{moment.introduction}</p><div className="energy-hygiene-preview"><p className="eyebrow">YOUR FOCUSED PRACTICE</p><b>{practice?.displayName}</b><small>{practice?.intendedResult}</small><span><Clock3 size={14} /> About {practice?.durationMinutes} minutes</span></div>{moment.id === "daily-hygiene" && <button className="text-button daily-ritual-picker-trigger" onClick={onChoosePlanRitual}>Choose a different ritual</button>}<button className="primary-button primary-button--wide" onClick={onBegin}>{moment.ctaLabel} <ArrowRight size={18} /></button><div className="energy-hygiene-screen-actions"><button className="secondary-button" onClick={onToggleShortcut}>{isShortcut ? "Remove home shortcut" : "Save to home"}</button>{moment.id === "daily-hygiene" && <button className="secondary-button" onClick={onToggleReminder}>{reminderActive ? "End seven-day reminder" : "Start a private seven-day reminder"}</button>}</div>{moment.id === "daily-hygiene" && <p className="energy-hygiene-reminder-note">Your selected ritual stays private to this plan. The same safety checks still apply before it begins.</p>}<button className="text-button" onClick={onBack}>Choose a different kind of energy care</button></section></main>; }
function DailyHygieneCompletionNote({ draft, onChange, onContinue, onSkip }: { draft: string; onChange: (value: string) => void; onContinue: () => void; onSkip: () => void }) { const moment = energyHygieneMoments.find((item) => item.id === "daily-hygiene")!; return <main className="flow-screen daily-hygiene-note-screen"><AppHeader onHome={onSkip} onSettings={onSkip} /><section className="settings-card daily-hygiene-note-card"><span className="energy-hygiene-mark"><Leaf size={25} /></span><p className="eyebrow">DAY-LEVEL REFLECTION</p><h1>Keep what feels useful.</h1><p>{moment.dailyPlan?.notePrompt}</p><label className="quiet-label"><textarea value={draft} onChange={(event) => onChange(event.target.value)} maxLength={1000} rows={5} placeholder="Optional and private to this device…" /></label><small className="daily-hygiene-note-card__privacy">This note stays in this browser as part of your seven-day plan.</small><div className="daily-hygiene-note-card__actions"><button className="secondary-button" onClick={onSkip}>Skip note</button><button className="primary-button" onClick={onContinue}>Continue <ArrowRight size={17} /></button></div></section></main>; }
function DailyHygieneRitualPicker({ initialPracticeId, onBack, onHome, onSettings, onStart }: { initialPracticeId: string; onBack: () => void; onHome: () => void; onSettings: () => void; onStart: (practiceId: string) => void }) { const moment = energyHygieneMoments.find((item) => item.id === "daily-hygiene")!; const [selectedId, setSelectedId] = useState(initialPracticeId); const selected = findCanonicalRitual(selectedId) ?? activeRituals[0]; return <main className="flow-screen daily-ritual-picker-screen"><AppHeader onHome={onHome} onSettings={onSettings} /><div className="flow-topline"><button className="back-button" onClick={onBack}><ArrowLeft size={18} /> Daily hygiene</button><span>YOUR SEVEN DAYS</span></div><section className="settings-card daily-ritual-picker-card"><span className="energy-hygiene-mark"><Leaf size={25} /></span><p className="eyebrow">CONFIRMED RITUAL LIBRARY</p><h1>{moment.dailyPlan?.pickerHeading}</h1><p>{moment.dailyPlan?.pickerDescription}</p><div className="daily-ritual-picker-list">{activeRituals.map((ritual) => <button key={ritual.id} className={`style-option ${selectedId === ritual.id ? "selected" : ""}`} onClick={() => setSelectedId(ritual.id)}><span><b>{ritual.displayName}</b><small>{ritual.intendedResult} · About {ritual.durationMinutes} minutes</small></span><i>{selectedId === ritual.id && <Check size={15} />}</i></button>)}</div><div className="energy-hygiene-preview"><p className="eyebrow">SELECTED FOR YOUR PLAN</p><b>{selected.displayName}</b><small>{selected.intendedResult}</small></div><button className="primary-button primary-button--wide" onClick={() => onStart(selected.id)}>Start seven days with this ritual <ArrowRight size={18} /></button></section></main>; }
function DailyHygieneReflection({ reminder, onHome, onSettings, onSave }: { reminder: DailyHygieneReminder; onHome: () => void; onSettings: () => void; onSave: (note: string) => void }) { const moment = energyHygieneMoments.find((item) => item.id === "daily-hygiene")!; const ritual = findCanonicalRitual(reminder.selectedPracticeId); const [draft, setDraft] = useState(reminder.reflectionNote); const progress = getDailyHygienePlanProgress(reminder); const insightEntries = Object.entries(reminder.completionNotes).sort(([left], [right]) => left.localeCompare(right)); return <main className="flow-screen daily-hygiene-reflection-screen"><AppHeader onHome={onHome} onSettings={onSettings} /><section className="settings-card daily-hygiene-reflection-card"><span className="energy-hygiene-mark"><Flower2 size={25} /></span><p className="eyebrow">DAY 7 · YOUR REFLECTION</p><h1>{moment.dailyPlan?.reflectionHeading}</h1><p>You completed {progress.completedCount} of 7 gentle check-ins with <b>{ritual?.displayName ?? "your chosen ritual"}</b>.</p><div className="daily-hygiene-reflection-card__insights"><p className="eyebrow">WHAT YOU NOTICED</p>{insightEntries.length ? insightEntries.map(([date, note], index) => <article key={date}><span>DAY {index + 1}</span><p>{note}</p></article>) : <p className="daily-hygiene-reflection-card__empty">You did not add daily notes, and that is completely okay. You can still notice what supported you.</p>}</div><label className="quiet-label"><span>{moment.dailyPlan?.reflectionPrompt}</span><textarea value={draft} onChange={(event) => setDraft(event.target.value)} maxLength={1200} rows={5} placeholder="Optional and private to this device…" /></label><small className="daily-hygiene-note-card__privacy">This reflection stays in this browser with your seven-day plan.</small><button className="primary-button primary-button--wide" onClick={() => onSave(draft)}>Save reflection and return home <ArrowRight size={18} /></button></section></main>; }
function DailyHygienePlanProgress({ reminder }: { reminder: DailyHygieneReminder }) { const progress = getDailyHygienePlanProgress(reminder); return <section className="daily-hygiene-progress" aria-label={`Seven-day daily hygiene plan: day ${progress.currentDay} of 7`}><div className="daily-hygiene-progress__heading"><div><p className="eyebrow">YOUR DAILY HYGIENE RHYTHM</p><h2>Day {progress.currentDay} of 7</h2></div><span>{progress.completedCount} completed</span></div><div className="daily-hygiene-progress__days" role="list" aria-label={`${progress.completedCount} of 7 daily practices completed`}>{Array.from({ length: 7 }, (_, index) => { const day = index + 1; const completed = progress.completedDays.includes(day); return <div key={day} role="listitem" className={`daily-hygiene-progress__day ${completed ? "is-complete" : ""} ${day === progress.currentDay ? "is-current" : ""}`}><i>{completed && <Check size={12} />}</i><small>Day {day}</small></div>; })}</div><p>{progress.completedCount ? "Each completed practice is marked here; your pace can stay gentle." : "Your plan begins whenever today’s practice feels supportive."}</p></section>; }
function HomeEnergyHygieneSupports({ reminder, reminderDue, shortcuts, onChoose, onDismiss, onEndReminder }: { reminder: DailyHygieneReminder | null; reminderDue: boolean; shortcuts: EnergyHygieneMoment[]; onChoose: (moment: EnergyHygieneMoment) => void; onDismiss: () => void; onEndReminder: () => void }) { const dailyMoment = energyHygieneMoments.find((moment) => moment.id === "daily-hygiene")!; return <>{reminder && reminderDue && <section className="daily-hygiene-reminder"><span className="daily-hygiene-reminder__mark"><Leaf size={18} /></span><div><p className="eyebrow">YOUR SEVEN-DAY DAILY HYGIENE</p><h2>Would a small capacity check support you today?</h2><p>Day {8 - remainingDailyHygieneReminderDays(reminder)} of 7. This private reminder appears only when you open the app.</p></div><div className="daily-hygiene-reminder__actions"><button className="primary-button" onClick={() => onChoose(dailyMoment)}>Continue today <ArrowRight size={16} /></button><button className="secondary-button" onClick={onDismiss}>Not today</button><button className="text-button" onClick={onEndReminder}>End plan</button></div></section>}{shortcuts.length > 0 && <section className="energy-hygiene-shortcuts"><div className="section-heading"><div><p className="eyebrow">SAVED ENERGY HYGIENE</p><h2>Return to your chosen care</h2></div><span className="section-number">{shortcuts.length} SAVED</span></div><div className="energy-hygiene-shortcuts__grid">{shortcuts.map((moment) => { const practice = findPracticeInCentralizedLibrary(moment.suggestedPracticeId); return <button key={moment.id} className="energy-hygiene-shortcut" onClick={() => onChoose(moment)}><span className="energy-hygiene-shortcut__mark"><Leaf size={18} /></span><span><p className="eyebrow">{moment.id === "after-interaction" ? "AFTER AN INTERACTION" : "DAILY RHYTHM"}</p><b>{moment.label}</b><small>{practice?.displayName}</small></span><ArrowRight size={18} /></button>; })}</div></section>}</>; }
function DashboardFooter() { return <footer className="home-footer home-footer--dashboard">The Energetic Safeguard is a general wellness and spiritual support tool. It does not diagnose or treat health conditions.</footer>; }
function ReorderableEnergyHygieneShortcuts({ shortcuts, onChoose, onReorder }: { shortcuts: EnergyHygieneMoment[]; onChoose: (moment: EnergyHygieneMoment) => void; onReorder: (source: EnergyHygieneShortcutId, target: EnergyHygieneShortcutId) => void }) { const [draggedId, setDraggedId] = useState<EnergyHygieneShortcutId | null>(null); if (!shortcuts.length) return null; return <section className="energy-hygiene-shortcuts"><div className="section-heading"><div><p className="eyebrow">SAVED ENERGY HYGIENE</p><h2>Return to your chosen care</h2><small>Drag a card to reorder it, or use the move buttons.</small></div><span className="section-number">{shortcuts.length} SAVED</span></div><div className="energy-hygiene-shortcuts__grid" role="list">{shortcuts.map((moment, index) => { const practice = findPracticeInCentralizedLibrary(moment.suggestedPracticeId); return <div key={moment.id} role="listitem" className={`energy-hygiene-shortcut-wrap ${draggedId === moment.id ? "is-dragging" : ""}`} draggable onDragStart={() => setDraggedId(moment.id)} onDragOver={(event) => event.preventDefault()} onDrop={() => { if (draggedId) onReorder(draggedId, moment.id); setDraggedId(null); }} onDragEnd={() => setDraggedId(null)} aria-grabbed={draggedId === moment.id}><button className="energy-hygiene-shortcut" onClick={() => onChoose(moment)}><span className="energy-hygiene-shortcut__mark"><Leaf size={18} /></span><span><p className="eyebrow">{moment.id === "after-interaction" ? "AFTER AN INTERACTION" : "DAILY RHYTHM"}</p><b>{moment.label}</b><small>{practice?.displayName}</small></span><ArrowRight size={18} /></button><div className="shortcut-order-controls" aria-label={`Reorder ${moment.label}`}><button disabled={index === 0} onClick={() => onReorder(moment.id, shortcuts[index - 1].id)} aria-label={`Move ${moment.label} earlier`}>Earlier</button><button disabled={index === shortcuts.length - 1} onClick={() => onReorder(moment.id, shortcuts[index + 1].id)} aria-label={`Move ${moment.label} later`}>Later</button></div></div>; })}</div></section>; }

function dailyAffirmation() { const seed = new Date().toDateString().split("").reduce((sum, character) => sum + character.charCodeAt(0), 0); return dailyAffirmations[seed % dailyAffirmations.length]; }

export default function Home() {
  const { isAuthenticated } = useAuth();
  const premiumStatus = trpc.premium.status.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  const checkoutMutation = trpc.premium.createCheckoutSession.useMutation();
  const libraryUtils = trpc.useUtils();
  const practiceHistory = trpc.library.history.useQuery({ limit: 50 }, { enabled: isAuthenticated, retry: false });
  const practiceFavorites = trpc.library.favorites.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  const dailyDefault = trpc.library.dailyDefault.useQuery(undefined, { enabled: isAuthenticated, retry: false });
  const recordCompletion = trpc.library.recordCompletion.useMutation();
  const updateHistoryNote = trpc.library.updateHistoryNote.useMutation();
  const saveFavorite = trpc.library.saveFavorite.useMutation();
  const removeFavorite = trpc.library.removeFavorite.useMutation();
  const setDailyDefault = trpc.library.setDailyDefault.useMutation();
  const [savedPreferences] = useState(() => loadPreferences());
  const [onboarded, setOnboarded] = useState(() => hasCompletedOnboarding());
  const [view, setView] = useState<View>(() => {
    if (typeof window !== "undefined" && new URLSearchParams(window.location.search).get("view") === "library") return "library";
    return hasCompletedOnboarding() ? "home" : "onboarding";
  });
  const [onboardingStep, setOnboardingStep] = useState(0);
  const [pathway, setPathway] = useState<FlowCategory>("morning");
  const [intakeStep, setIntakeStep] = useState(0);
  const [query, setQuery] = useState<PracticeQuery>(() => makeDefaultQuery("morning", savedPreferences.practiceStyle));
  const [settingsStyle, setSettingsStyle] = useState<StoredPracticeStyle>(savedPreferences.practiceStyle);
  const [energyHygieneShortcutIds, setEnergyHygieneShortcutIds] = useState(savedPreferences.energyHygieneShortcutIds);
  const [activeStep, setActiveStep] = useState(0);
  const [shortVersion, setShortVersion] = useState(false);
  const [forcedPracticeId, setForcedPracticeId] = useState<string | null>(null);
  const [commitment, setCommitment] = useState<SevenDayCommitment | null>(() => loadSevenDayCommitment());
  const [textSize, setTextSize] = useState<StoredTextSize>(savedPreferences.textSize);
  const [reducedMotion, setReducedMotion] = useState(savedPreferences.reducedMotion);
  const [favoritePathwayFilter, setFavoritePathwayFilter] = useState<FlowCategory | "all">("all");
  const [favoriteRoseRayFilter, setFavoriteRoseRayFilter] = useState<RoseRayId | "all">("all");
  const [favoriteKeyword, setFavoriteKeyword] = useState("");
  const [editingHistoryNoteId, setEditingHistoryNoteId] = useState<number | null>(null);
  const [historyNoteDraft, setHistoryNoteDraft] = useState("");
  const [safetyHandoff, setSafetyHandoff] = useState<SafetyHandoff | null>(null);
  const [dailyHygieneReminder, setDailyHygieneReminder] = useState(() => loadDailyHygieneReminder());
  const [dailyHygieneSessionActive, setDailyHygieneSessionActive] = useState(false);
  const [dailyHygieneNoteDraft, setDailyHygieneNoteDraft] = useState("");

  const recommendation = useMemo(() => recommendPractice(query), [query]);
  const activePractice = useMemo<Practice>(() => findPracticeInCentralizedLibrary(forcedPracticeId) ?? recommendation, [forcedPracticeId, recommendation]);
  const visibleSteps = shortVersion ? activePractice.shortVersion : activePractice.steps;
  // Guided practices are intentionally unrestricted; no trial or purchase gate is applied.
  const hasPremiumAccess = true;
  const freePracticesRemaining = 0;
  const activePracticeIsFavorite = practiceFavorites.data?.some((favorite) => favorite.practiceId === activePractice.id) ?? false;
  const flow = getFlow(pathway)!;
  const pathwayCards = useMemo(() => supportFlows.filter((item) => item.showOnDashboard).map((item) => ({ ...item, icon: flowIcons[item.iconKey], asset: item.artworkKey === "arrival" ? ASSETS.arrival : item.artworkKey === "boundary" ? ASSETS.boundary : undefined })), []);
  const catalogSuggestedPractice = practices.find((practice) => practice.id === getFlow("morning")?.suggestedPracticeId) ?? practices[0];
  const suggestedPractice = practices.find((practice) => practice.id === dailyDefault.data) ?? catalogSuggestedPractice;
  const dailyDefaultPractice = practices.find((practice) => practice.id === dailyDefault.data) ?? null;
  const suggestedRoseRay = suggestedPractice.roseRayId ? roseRays[suggestedPractice.roseRayId] : undefined;
  const filteredFavorites = useMemo(() => filterSavedPractices(practiceFavorites.data ?? [], { pathway: favoritePathwayFilter, roseRayId: favoriteRoseRayFilter, keyword: favoriteKeyword }), [favoriteKeyword, favoritePathwayFilter, favoriteRoseRayFilter, practiceFavorites.data]);
  const energyHygieneShortcuts = energyHygieneShortcutIds.flatMap((id) => energyHygieneMoments.find((moment) => moment.id === id) ?? []);
  const dailyHygieneReminderDue = Boolean(dailyHygieneReminder && isDailyHygieneReminderDue(dailyHygieneReminder));

  useEffect(() => { document.documentElement.dataset.textSize = textSize; document.documentElement.dataset.motion = reducedMotion ? "reduced" : "full"; }, [reducedMotion, textSize]);
  useEffect(() => { savePreferences({ practiceStyle: settingsStyle, reducedMotion, textSize, energyHygieneShortcutIds }); }, [energyHygieneShortcutIds, reducedMotion, settingsStyle, textSize]);
  useEffect(() => { if (dailyHygieneSessionActive && !["recommendation", "practice", "daily-note", "complete", "daily-reflection"].includes(view)) setDailyHygieneSessionActive(false); }, [dailyHygieneSessionActive, view]);
  useEffect(() => { if (view !== "loading") return; const timer = window.setTimeout(() => setView("recommendation"), 650); return () => window.clearTimeout(timer); }, [view]);
  useEffect(() => { const checkout = new URLSearchParams(window.location.search).get("checkout"); if (checkout === "success") { toast.success("Payment received. Your premium access will be available shortly."); void premiumStatus.refetch(); window.history.replaceState({}, "", window.location.pathname); } if (checkout === "cancelled") { toast.message("Checkout was cancelled. Your free practices are still available."); window.history.replaceState({}, "", window.location.pathname); } }, []);

  function updateQuery<K extends keyof PracticeQuery>(key: K, value: PracticeQuery[K]) { setQuery((current) => ({ ...current, [key]: value })); }
  function canUseGuidedFlow() { return true; }
  function beginPathway(nextPathway: FlowCategory) { if (!canUseGuidedFlow()) return; setPathway(nextPathway); setQuery(makeDefaultQuery(nextPathway, settingsStyle)); setForcedPracticeId(null); setIntakeStep(0); setView(nextPathway === "hygiene" ? "hygiene-choice" : "intake"); }
  function chooseEnergyHygieneMoment(moment: EnergyHygieneMoment) { setPathway("hygiene"); setQuery({ ...makeDefaultQuery("hygiene", settingsStyle), situation: moment.situation }); setForcedPracticeId(moment.suggestedPracticeId); setShortVersion(false); setActiveStep(0); setView(moment.id === "after-interaction" ? "hygiene-restore" : "hygiene-daily"); }
  function beginEnergyHygienePractice(moment: EnergyHygieneMoment) { const requestedPractice = moment.id === "daily-hygiene" ? findCanonicalRitual(dailyHygieneReminder?.selectedPracticeId ?? moment.suggestedPracticeId) : findCanonicalRitual(moment.suggestedPracticeId); const selectedPathway = requestedPractice?.flowCategory[0] ?? "hygiene"; const nextQuery = { ...makeDefaultQuery(selectedPathway, settingsStyle), situation: moment.situation, intensity: Math.min(requestedPractice?.intensityRange[1] ?? 5, Math.max(requestedPractice?.intensityRange[0] ?? 1, 5)), availableMinutes: Math.max(3, requestedPractice?.durationMinutes ?? 3) }; const selection = selectLiveSafetyAwarePractice(nextQuery, requestedPractice ? [requestedPractice.id] : undefined); setPathway(selectedPathway); setQuery(nextQuery); setShortVersion(false); setActiveStep(0); setDailyHygieneNoteDraft(""); setDailyHygieneSessionActive(moment.id === "daily-hygiene" && Boolean(dailyHygieneReminder)); if (selection.kind === "safety-handoff") { setSafetyHandoff(selection); setView("safety"); return; } setSafetyHandoff(null); setForcedPracticeId(selection.ritual.id); setView("recommendation"); }
  function toggleEnergyHygieneShortcut(id: EnergyHygieneShortcutId) { setEnergyHygieneShortcutIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); }
  function reorderEnergyHygieneShortcut(sourceId: EnergyHygieneShortcutId, targetId: EnergyHygieneShortcutId) { setEnergyHygieneShortcutIds((current) => reorderEnergyHygieneShortcuts(current, sourceId, targetId)); }
  function toggleDailyHygieneReminder() { if (dailyHygieneReminder) { clearDailyHygieneReminder(); setDailyHygieneReminder(null); return; } const next = createDailyHygieneReminder("energy-conservation-pause"); saveDailyHygieneReminder(next); setDailyHygieneReminder(next); }
  function beginDailyHygienePlan(practiceId: string) { const next = createDailyHygieneReminder(practiceId); saveDailyHygieneReminder(next); setDailyHygieneReminder(next); setView("hygiene-daily"); }
  function dismissDailyReminderForToday() { if (!dailyHygieneReminder) return; const next = dismissDailyHygieneReminderForToday(dailyHygieneReminder); saveDailyHygieneReminder(next); setDailyHygieneReminder(next); }
  function beginQuickReset() { const quick = getFlow("emergency")?.suggestedPracticeId; if (!quick) return; setSafetyHandoff(null); setPathway("emergency"); setQuery(makeDefaultQuery("emergency", settingsStyle)); setForcedPracticeId(quick); setShortVersion(false); setActiveStep(0); setView("practice"); }
  function beginSuggestedPractice() { setPathway("morning"); setQuery(makeDefaultQuery("morning", settingsStyle)); setForcedPracticeId(suggestedPractice.id); setShortVersion(false); setActiveStep(0); setView("practice"); }
  function toggleAdjustment(id: string) { setQuery((current) => ({ ...current, adjustments: current.adjustments.includes(id) ? current.adjustments.filter((item) => item !== id) : [...current.adjustments, id] })); }
  function advanceIntake() { const selection = selectLiveSafetyAwarePractice(query); if (selection.kind === "safety-handoff") { setSafetyHandoff(selection); setView("safety"); return; } if (intakeStep < 2) { setIntakeStep((step) => step + 1); return; } setSafetyHandoff(null); setForcedPracticeId(selection.ritual.id); setView("loading"); }
  function startPractice(short = false) { if (!canUseGuidedFlow()) return; setShortVersion(short); setActiveStep(0); setView("practice"); }
  function toggleSevenDayCommitment() { if (commitment?.practiceId === activePractice.id) { clearSevenDayCommitment(); setCommitment(null); return; } const next = createSevenDayCommitment(activePractice.id, activePractice.displayName); saveSevenDayCommitment(next); setCommitment(next); }
  function finishPractice(response: "home" | "safety") { if (response === "safety") { setSafetyHandoff(null); setView("safety"); return; } if (isAuthenticated) recordCompletion.mutate({ practiceId: activePractice.id }, { onSuccess: () => void libraryUtils.library.history.invalidate() }); if (dailyHygieneSessionActive && dailyHygieneReminder) { const completed = completeDailyHygieneForToday(dailyHygieneReminder); const next = setDailyHygieneNoteForToday(completed, dailyHygieneNoteDraft); saveDailyHygieneReminder(next); setDailyHygieneReminder(next); setDailyHygieneSessionActive(false); setDailyHygieneNoteDraft(""); if (getDailyHygienePlanProgress(next).currentDay === 7) { setView("daily-reflection"); return; } } setView("home"); }
  function beginSavedPractice(practiceId: string) { const savedPractice = findPracticeInCentralizedLibrary(practiceId); if (!savedPractice) return; setPathway(savedPractice.flowCategory[0]); setQuery(makeDefaultQuery(savedPractice.flowCategory[0], settingsStyle)); setForcedPracticeId(savedPractice.id); setShortVersion(false); setActiveStep(0); setView("practice"); }
  function toggleActiveFavorite() { if (!isAuthenticated) { toast.message("Sign in to save favorites and keep them with your account."); startLogin(); return; } const input = { practiceId: activePractice.id }; const refreshFavorites = () => { void libraryUtils.library.favorites.invalidate(); void libraryUtils.library.dailyDefault.invalidate(); }; if (activePracticeIsFavorite) removeFavorite.mutate(input, { onSuccess: () => { toast.success("Removed from favorites."); refreshFavorites(); }, onError: () => toast.error("We could not update this favorite.") }); else saveFavorite.mutate(input, { onSuccess: () => { toast.success("Saved to your favorites."); refreshFavorites(); }, onError: () => toast.error("We could not save this favorite.") }); }
  function openHistoryNote(entryId: number, note: string | null) { setEditingHistoryNoteId(entryId); setHistoryNoteDraft(note ?? ""); }
  function saveHistoryNote(entryId: number) { updateHistoryNote.mutate({ historyId: entryId, note: historyNoteDraft.trim() || null }, { onSuccess: () => { toast.success("Private note saved."); setEditingHistoryNoteId(null); void libraryUtils.library.history.invalidate(); }, onError: () => toast.error("We could not save this note.") }); }
  function deleteHistoryNote(entryId: number) { updateHistoryNote.mutate({ historyId: entryId, note: null }, { onSuccess: () => { toast.success("Private note deleted."); void libraryUtils.library.history.invalidate(); }, onError: () => toast.error("We could not delete this note.") }); }
  function exportHistoryNotes() { const notes = (practiceHistory.data ?? []).flatMap((entry) => { const practice = practices.find((item) => item.id === entry.practiceId); return entry.note && practice ? [{ practice, entry }] : []; }); if (!notes.length) { toast.message("There are no private notes to export yet."); return; } const contents = notes.map(({ practice, entry }) => `${practice.displayName}\nCompleted: ${new Date(entry.completedAt).toLocaleDateString()}\n\n${entry.note}`).join("\n\n---\n\n"); const url = URL.createObjectURL(new Blob([contents], { type: "text/plain" })); const link = document.createElement("a"); link.href = url; link.download = "energetic-safeguard-private-notes.txt"; link.click(); URL.revokeObjectURL(url); }
  function selectDailyDefault(practiceId: string | null) { setDailyDefault.mutate({ practiceId }, { onSuccess: () => { toast.success(practiceId ? "Daily default saved." : "Daily default cleared."); void libraryUtils.library.dailyDefault.invalidate(); }, onError: () => toast.error("Your daily default must be one of your saved favorites.") }); }
  function completeOnboarding() { saveOnboardingCompleted(); setOnboarded(true); setView("home"); }
  function beginCheckout(offerKey: PremiumOfferKey) { if (!isAuthenticated) { toast.message("Sign in to keep your lifetime purchase connected to you."); startLogin(); return; } checkoutMutation.mutate({ offerKey }, { onSuccess: (result) => { if (result.alreadyPremium) { toast.success("Your account already has premium access."); void premiumStatus.refetch(); } else if (result.checkoutUrl) { toast.message("Opening secure checkout in a new tab."); window.open(result.checkoutUrl, "_blank", "noopener,noreferrer"); } }, onError: () => toast.error("We could not open checkout. Please try again.") }); }

  if (view === "hygiene-choice") return <div className="app-shell"><div className="paper-grain" /><EnergyHygieneChoice onHome={() => setView("home")} onSettings={() => setView("settings")} onChoose={chooseEnergyHygieneMoment} /><button className="quick-reset-fab" onClick={beginQuickReset}><Bolt size={16} /><span>Need a Quick Reset?</span></button></div>;
  if (view === "hygiene-restore" || view === "hygiene-daily") { const moment = energyHygieneMoments.find((item) => item.id === (view === "hygiene-restore" ? "after-interaction" : "daily-hygiene"))!; return <div className="app-shell"><div className="paper-grain" /><EnergyHygieneMomentScreen moment={moment} onHome={() => setView("home")} onSettings={() => setView("settings")} onBack={() => setView("hygiene-choice")} onBegin={() => beginEnergyHygienePractice(moment)} isShortcut={energyHygieneShortcutIds.includes(moment.id)} onToggleShortcut={() => toggleEnergyHygieneShortcut(moment.id)} reminderActive={Boolean(dailyHygieneReminder)} onToggleReminder={toggleDailyHygieneReminder} dailySelectedPractice={moment.id === "daily-hygiene" ? findCanonicalRitual(dailyHygieneReminder?.selectedPracticeId) : null} onChoosePlanRitual={() => setView("daily-ritual-picker")} /><button className="quick-reset-fab" onClick={beginQuickReset}><Bolt size={16} /><span>Need a Quick Reset?</span></button></div>; }
  if (view === "daily-ritual-picker") return <div className="app-shell"><div className="paper-grain" /><DailyHygieneRitualPicker initialPracticeId={dailyHygieneReminder?.selectedPracticeId ?? "energy-conservation-pause"} onHome={() => setView("home")} onSettings={() => setView("settings")} onBack={() => setView("hygiene-daily")} onStart={beginDailyHygienePlan} /></div>;
  if (view === "daily-note") return <div className="app-shell"><div className="paper-grain" /><DailyHygieneCompletionNote draft={dailyHygieneNoteDraft} onChange={setDailyHygieneNoteDraft} onContinue={() => setView("complete")} onSkip={() => { setDailyHygieneNoteDraft(""); setView("complete"); }} /></div>;
  if (view === "daily-reflection" && dailyHygieneReminder) return <div className="app-shell"><div className="paper-grain" /><DailyHygieneReflection reminder={dailyHygieneReminder} onHome={() => setView("home")} onSettings={() => setView("settings")} onSave={(note) => { const next = setDailyHygieneReflection(dailyHygieneReminder, note); saveDailyHygieneReminder(next); setDailyHygieneReminder(next); setView("home"); }} /></div>;

  return <div className="app-shell"><div className="paper-grain" />
    {view === "onboarding" && <main className="onboarding-screen"><header className="onboarding-header"><div className="wordmark"><RoseMark compact /><span><b>Energetic</b> Safeguard</span></div><button className="text-button" onClick={completeOnboarding}>Skip</button></header><section className="onboarding-card">{onboardingStep === 0 && <><div className="onboarding-orb"><RoseMark /></div><p className="eyebrow">WELCOME</p><h1>Welcome to The Energetic Safeguard</h1><p className="onboarding-tagline"><em>Ground your energy.</em><em>Protect your peace.</em><em>Return to yourself.</em></p></>}{onboardingStep === 1 && <><div className="onboarding-orb"><Compass size={29} /></div><p className="eyebrow">ONE CLEAR NEXT STEP</p><h1>One supportive practice, chosen for right now.</h1><p className="onboarding-copy">The app considers the parts of a moment that shape what could feel supportive.</p><div className="onboarding-factors">{["How you’re feeling", "Your situation", "Your available time", "Your preferences"].map((factor) => <span key={factor}><Sparkles size={14} />{factor}</span>)}</div></>}{onboardingStep === 2 && <><p className="eyebrow">YOUR DEFAULT</p><h1>Choose your practice style.</h1><p className="onboarding-copy">You can change this any time in Settings, or for one practice inside a pathway.</p><div className="onboarding-styles">{practiceStyleOptions.map((style) => <button key={style.id} className={`style-option ${settingsStyle === style.id ? "selected" : ""}`} onClick={() => setSettingsStyle(style.id)}><span><b>{style.label}</b><small>{style.note}</small></span><i>{settingsStyle === style.id && <Check size={15} />}</i></button>)}</div><p className="onboarding-note">A physical crystal is never required for any practice.</p></>}<div className="onboarding-controls"><button className="secondary-button" onClick={() => onboardingStep ? setOnboardingStep((step) => step - 1) : completeOnboarding()}>{onboardingStep ? "Back" : "Skip"}</button><IntakeProgress step={onboardingStep} /><button className="primary-button" onClick={() => onboardingStep < 2 ? setOnboardingStep((step) => step + 1) : completeOnboarding()}>{onboardingStep < 2 ? "Continue" : "Begin"}<ArrowRight size={17} /></button></div></section></main>}
    {view === "home" && <main className="home-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><section className="home-hero"><div className="hero-copy"><p className="eyebrow">A GUIDE FOR THIS MOMENT</p><h1>Ground your energy.<br /><em>Protect your peace.</em><br />Return to yourself.</h1><p className="hero-description">Answer a few simple questions and receive one clear practice to help you ground, protect your capacity, or reset.</p><button className="primary-button" onClick={() => beginPathway("reset")}>Find support for right now <ArrowRight size={18} /></button></div><div className="hero-art" aria-hidden="true"><img src={ASSETS.roseField} alt="" /><div className="hero-art__overlay"><RoseMark /></div></div></section>{!hasPremiumAccess && <div className="free-practice-note"><span><Sparkles size={15} /></span><p><b>{freePracticesRemaining} of 3 free practices remaining</b><small>Complete a guided practice to use one. Your One-Minute Reset remains here whenever you need it.</small></p></div>}<section className="daily-guidance"><p className="eyebrow">A GENTLE REMINDER</p><blockquote>“{dailyAffirmation()}”</blockquote><div className="suggested-practice"><div><p className="eyebrow">TODAY’S SUGGESTED PRACTICE</p><h3>{suggestedPractice.displayName}</h3><p>{suggestedPractice.intendedResult}</p><small><Clock3 size={13} /> {suggestedPractice.durationMinutes} minutes{suggestedRoseRay ? ` · ${suggestedRoseRay.name}` : ""}</small></div><button className="secondary-button" onClick={beginSuggestedPractice}>Begin <Play size={15} fill="currentColor" /></button></div></section><section className="pathways-section"><div className="section-heading"><div><p className="eyebrow">CHOOSE A PATHWAY</p><h2>What would feel supportive?</h2></div><span className="section-number">01 — 05</span></div><div className="pathway-list">{pathwayCards.map((item, index) => { const Icon = item.icon; return <button key={item.id} className={`pathway-card pathway-card--${item.tint} ${item.asset ? "has-art" : ""}`} onClick={() => beginPathway(item.id)}>{item.asset && <img className="pathway-art" src={item.asset} alt="" />}<div className="pathway-card__inner"><span className="card-number">0{index + 1}</span><div className="card-icon"><Icon size={23} /></div><p className="pathway-label">{item.dashboardLabel}</p><h3>{item.title}</h3><p>{item.description}</p><span className="card-arrow"><ChevronRight size={21} /></span></div></button>; })}</div></section>{commitment && <section className="remembered-commitment"><span className="commitment-mark"><RotateCcw size={18} /></span><div><p className="eyebrow">YOUR SEVEN-DAY INTENTION</p><b>{commitment.practiceName}</b><small>{remainingCommitmentDays(commitment)} {remainingCommitmentDays(commitment) === 1 ? "day" : "days"} remaining. Return when the pattern appears.</small></div><button onClick={() => { clearSevenDayCommitment(); setCommitment(null); }}>End commitment</button></section>}<footer className="home-footer">The Energetic Safeguard is a general wellness and spiritual support tool. It does not diagnose or treat health conditions.</footer></main>}
    {view === "home" && dailyDefaultPractice && <section className="home-daily-default"><span><Heart size={17} fill="currentColor" /></span><div><p className="eyebrow">YOUR DAILY DEFAULT</p><b>{dailyDefaultPractice.displayName}</b><small>{dailyDefaultPractice.intendedResult}</small></div><button onClick={() => beginSavedPractice(dailyDefaultPractice.id)}>Begin <Play size={14} fill="currentColor" /></button></section>}
    {view === "home" && dailyHygieneReminder && <DailyHygienePlanProgress reminder={dailyHygieneReminder} />}
    {view === "home" && <><HomeEnergyHygieneSupports reminder={dailyHygieneReminder} reminderDue={dailyHygieneReminderDue} shortcuts={[]} onChoose={chooseEnergyHygieneMoment} onDismiss={dismissDailyReminderForToday} onEndReminder={toggleDailyHygieneReminder} /><ReorderableEnergyHygieneShortcuts shortcuts={energyHygieneShortcuts} onChoose={chooseEnergyHygieneMoment} onReorder={reorderEnergyHygieneShortcut} /><DashboardFooter /></>}
    {view === "intake" && <main className="flow-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><div className="flow-topline"><button className="back-button" onClick={() => intakeStep ? setIntakeStep((step) => step - 1) : setView("home")}><ArrowLeft size={18} /> Back</button><IntakeProgress step={intakeStep} /><span>{intakeStep + 1} / 3</span></div><section className="intake-card"><div className="intake-context"><span className={`context-icon context-icon--${flow.tint}`}>{(() => { const Icon = flowIcons[flow.iconKey]; return <Icon size={21} />; })()}</span><div><p className="eyebrow">{flow.dashboardLabel}</p><h2>{flow.title}</h2></div></div>{intakeStep === 0 && <div className="intake-step"><h1>{flow.intake.question}</h1><div className="option-stack">{flow.intake.options.map((option) => <button key={option} className={`choice-row ${query.situation === option ? "selected" : ""}`} onClick={() => updateQuery("situation", option)}><span>{option}</span><i>{query.situation === option && <Check size={16} />}</i></button>)}</div><label className="quiet-label">Or describe it in your own words<textarea value={query.situation} onChange={(event) => updateQuery("situation", event.target.value)} placeholder="Only share what feels comfortable." rows={2} /></label></div>}{intakeStep === 1 && <div className="intake-step"><h1>How much is this asking of you?</h1><div className="intensity-readout"><strong>{query.intensity}</strong><span>out of 10</span></div><input className="range-input" type="range" min="1" max="10" value={query.intensity} onChange={(event) => updateQuery("intensity", Number(event.target.value))} /><div className="range-captions"><span>Lightly present</span><span>Very intense</span></div><div className="question-split"><div><p className="form-label">Energy available</p><div className="segmented">{(["low", "steady", "high"] as const).map((level) => <button key={level} className={query.energy === level ? "active" : ""} onClick={() => updateQuery("energy", level)}>{level}</button>)}</div></div><div><p className="form-label">Time you have</p><div className="segmented">{([1, 3, 5] as const).map((minutes) => <button key={minutes} className={query.availableMinutes === minutes ? "active" : ""} onClick={() => updateQuery("availableMinutes", minutes)}>{minutes}m</button>)}</div></div></div><p className="form-label form-label--space">Where are you?</p><div className="location-row">{(["anywhere", "home", "work", "public", "transit", "outdoors"] as Location[]).map((location) => <button key={location} className={query.location === location ? "active" : ""} onClick={() => updateQuery("location", location)}>{location === "anywhere" ? "Anywhere" : location}</button>)}</div></div>}{intakeStep === 2 && <div className="intake-step"><h1>Would you like to make any adjustments?</h1><p className="lead-copy">You can choose what feels supportive, or leave everything as it is.</p><div className="adjustment-stack">{adjustmentOptions.map(([id, label]) => <button key={id} className={`check-row ${query.adjustments.includes(id) ? "selected" : ""}`} onClick={() => toggleAdjustment(id)}><i>{query.adjustments.includes(id) && <Check size={15} />}</i><span>{label}</span></button>)}</div><p className="form-label form-label--space">Practice style for this moment</p><div className="style-list">{practiceStyleOptions.map((style) => <button key={style.id} className={`style-option ${query.style === style.id ? "selected" : ""}`} onClick={() => updateQuery("style", style.id)}><span><b>{style.label}</b><small>{style.note}</small></span><i>{query.style === style.id && <Check size={15} />}</i></button>)}</div></div>}<button className="primary-button intake-continue" disabled={intakeStep === 0 && !query.situation.trim()} onClick={advanceIntake}>{intakeStep === 2 ? "Find my practice" : "Continue"}<ArrowRight size={18} /></button></section></main>}
    {view === "loading" && <main className="loading-screen"><RoseMark /><p className="eyebrow">A MOMENT OF CARE</p><h1>Finding your best support…</h1><span className="loading-line" /></main>}
    {view === "recommendation" && <main className="flow-screen recommendation-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><button className="back-button recommendation-back" onClick={() => setView("intake")}><ArrowLeft size={18} /> Adjust answers</button><section className="recommendation-card"><div className="recommendation-orb"><RoseMark /></div><p className="eyebrow">TODAY’S RECOMMENDATION</p><h1>{activePractice.displayName}</h1><p className="recommendation-result">{activePractice.intendedResult}</p><div className="hearing-box"><span><HeartHandshake size={19} /></span><div><p className="eyebrow">WHY THIS WAS CHOSEN</p><p>You shared that this moment feels <b>{query.intensity >= 7 ? "especially intense" : query.intensity >= 4 ? "somewhat demanding" : "present"}</b>, with <b>{query.availableMinutes} {query.availableMinutes === 1 ? "minute" : "minutes"}</b> available. {recommendationReason(activePractice, query)}</p></div></div><div className="practice-meta"><span><Clock3 size={17} /> About {activePractice.durationMinutes} {activePractice.durationMinutes === 1 ? "minute" : "minutes"}</span><span><Sparkles size={17} /> Best for {query.situation || "this moment"}</span></div>{activePractice.roseRayId && <div className="why-box"><p className="eyebrow">OPTIONAL SYMBOLIC SUPPORT</p><p>{roseRays[activePractice.roseRayId].name} — {roseRays[activePractice.roseRayId].symbolicTheme}.</p><small>You may imagine, sense, or simply use this as an intention.</small></div>}<button className="primary-button primary-button--wide" onClick={() => startPractice()}><Play size={17} fill="currentColor" /> Begin practice</button>{activePractice.shortVersion.length > 0 && <button className="text-button" onClick={() => startPractice(true)}>Show a shorter option</button>}</section></main>}
    {view === "practice" && <main className="flow-screen practice-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><div className="practice-header"><button className="back-button" onClick={() => setView("recommendation")}><ArrowLeft size={18} /> Back</button><span>{shortVersion ? "SHORT OPTION" : `STEP ${activeStep + 1} OF ${visibleSteps.length}`}</span><button className="stop-button" onClick={() => setView("recommendation")}><Pause size={15} /> Stop for now</button></div><section className="guided-card"><div className="guided-orb"><span className="orb-ring orb-ring--one" /><span className="orb-ring orb-ring--two" /><RoseMark /></div><p className="eyebrow">{activePractice.displayName}</p><h1>{visibleSteps[activeStep].title}</h1><p className="guided-instruction">{visibleSteps[activeStep].instruction}</p><div className="step-progress"><span style={{ width: `${((activeStep + 1) / visibleSteps.length) * 100}%` }} /></div><div className="practice-controls"><button className="secondary-button" disabled={activeStep === 0} onClick={() => setActiveStep((step) => Math.max(0, step - 1))}>Previous</button><button className="primary-button" onClick={() => activeStep < visibleSteps.length - 1 ? setActiveStep((step) => step + 1) : setView(dailyHygieneSessionActive ? "daily-note" : "complete")}>{activeStep < visibleSteps.length - 1 ? "Next step" : "I completed this"}<ArrowRight size={18} /></button></div><button className="overwhelmed-button" onClick={() => setView("safety")}>I feel more overwhelmed</button></section></main>}
    {view === "complete" && <main className="flow-screen complete-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><section className="complete-card"><div className="completion-flower"><Flower2 size={39} /></div><p className="eyebrow">A PAUSE, COMPLETED</p><h1>Beautiful work.</h1><p>Even a small pause can help you reconnect with yourself. {activePractice.closingCheckIn}</p><div className="completion-options"><button onClick={() => finishPractice("home")}>More grounded</button><button onClick={() => finishPractice("home")}>About the same</button><button onClick={() => finishPractice("safety")}>More overwhelmed</button><button onClick={() => finishPractice("home")}>I’m not sure</button></div>{pathway === "hygiene" && <div className="commitment-box"><div><b>A seven-day intention</b><span>Repeat this practice when the pattern appears.</span></div><button className={commitment?.practiceId === activePractice.id ? "commitment-active" : ""} onClick={toggleSevenDayCommitment}>{commitment?.practiceId === activePractice.id ? <><Check size={16} /> Chosen</> : commitment ? "Replace" : "Choose this"}</button></div>}<button className="text-button" onClick={() => setView("home")}>Return home</button></section></main>}
    {view === "library" && <main className="flow-screen library-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><section className="library-card"><div className="library-heading"><div><p className="eyebrow">YOUR ACCOUNT LIBRARY</p><h1>Saved support</h1><p>Keep the practices you return to and a quiet record of the moments you completed.</p></div><button className="icon-button" onClick={() => setView("home")} aria-label="Close library"><X size={20} /></button></div>{!isAuthenticated ? <div className="library-signin"><div className="library-signin-mark"><Heart size={24} /></div><h2>Keep your practices with you.</h2><p>Sign in to save favorite meditations and view your recent completed practices across devices.</p><button className="primary-button" onClick={startLogin}>Sign in to your library <ArrowRight size={17} /></button></div> : <><section className="library-section"><div className="library-section-heading"><div><p className="eyebrow">FAVORITES</p><h2>Your saved meditations</h2></div><span>{practiceFavorites.data?.length ?? 0}</span></div>{practiceFavorites.isLoading ? <p className="library-status">Gathering your saved practices…</p> : practiceFavorites.data?.length ? <div className="library-list">{practiceFavorites.data.map((favorite) => { const saved = practices.find((practice) => practice.id === favorite.practiceId); return saved ? <article className="library-item" key={favorite.id}><div className="library-item-mark"><Heart size={16} fill="currentColor" /></div><div><b>{saved.displayName}</b><small>{saved.durationMinutes} {saved.durationMinutes === 1 ? "minute" : "minutes"} · {saved.intendedResult}</small></div><button onClick={() => beginSavedPractice(saved.id)}>Begin <Play size={14} fill="currentColor" /></button></article> : null; })}</div> : <div className="library-empty"><Heart size={20} /><p><b>No favorites yet</b><span>Save a practice from its recommendation card to find it here.</span></p></div>}</section><section className="library-section"><div className="library-section-heading"><div><p className="eyebrow">RECENT PRACTICES</p><h2>Your gentle record</h2></div><span>{practiceHistory.data?.length ?? 0}</span></div>{practiceHistory.isLoading ? <p className="library-status">Gathering your recent practices…</p> : practiceHistory.data?.length ? <div className="library-list">{practiceHistory.data.map((entry) => { const completed = practices.find((practice) => practice.id === entry.practiceId); return completed ? <article className="library-item library-item--history" key={entry.id}><div className="library-item-mark"><Check size={16} /></div><div><b>{completed.displayName}</b><small>Completed {new Date(entry.completedAt).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}</small></div><button onClick={() => beginSavedPractice(completed.id)}>Again <RotateCcw size={14} /></button></article> : null; })}</div> : <div className="library-empty"><Clock3 size={20} /><p><b>Your practice record will appear here</b><span>Complete a practice while signed in to create a simple, private history.</span></p></div>}</section></>}</section></main>}
    {view === "paywall" && <main className="flow-screen paywall-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><section className="paywall-card"><div className="paywall-mark"><RoseMark /></div><p className="eyebrow">YOUR THREE FREE PRACTICES ARE COMPLETE</p><h1>Continue with a lifetime of support.</h1><p className="paywall-intro">Choose the access that feels right. Both offers are one-time payments; there is no subscription.</p><div className="offer-stack"><article className="offer-card"><span className="offer-kicker">AS IT IS TODAY</span><h2>Current App Lifetime</h2><strong>$19 <small>USD</small></strong><p>Permanent access to today’s guided pathways and curated practice library.</p><button className="secondary-button secondary-button--wide" disabled={checkoutMutation.isPending} onClick={() => beginCheckout("current_app_lifetime")}>{checkoutMutation.isPending ? "Preparing checkout…" : "Choose current app"}</button></article><article className="offer-card offer-card--featured"><span className="offer-kicker">MOST COMPLETE</span><h2>Lifetime + Future Updates</h2><strong>$39 <small>USD</small></strong><p>Everything available today, plus future in-app practice and meditation content.</p><button className="primary-button primary-button--wide" disabled={checkoutMutation.isPending} onClick={() => beginCheckout("future_updates_lifetime")}>{checkoutMutation.isPending ? "Preparing checkout…" : "Choose future updates"}</button></article></div><p className="paywall-footnote">You will be asked to sign in before secure checkout so your lifetime access stays connected to you.</p><button className="text-button" onClick={() => setView("home")}>Return home</button></section></main>}
    {view === "safety" && <main className="safety-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><section className="safety-card"><div className="safety-symbol"><ShieldCheck size={34} /></div><p className="eyebrow">PAUSE HERE</p><h1>{safetyHandoff?.priority === "high" ? "You do not need to push through this." : "You can stop this practice."}</h1><p>{safetyHandoff?.supportMessage ?? "This is a general wellness and spiritual support tool. It cannot assess what you need in an emergency."}</p><div className="orientation-note"><b>For this moment</b><span>{safetyHandoff?.orientationSteps[0] ?? "With your eyes open, notice one stable object and one point of support beneath or beside you."}</span>{safetyHandoff?.orientationSteps.slice(1).map((step) => <span key={step}>{step}</span>)}</div><p>If you feel physically unsafe, in immediate danger, or unable to stay safe, please move toward a safer place and contact appropriate personal, professional, medical, crisis, or emergency support.</p><button className="primary-button primary-button--wide" onClick={beginQuickReset}>Try a one-minute orientation <ArrowRight size={18} /></button><button className="text-button" onClick={() => { setSafetyHandoff(null); setView("home"); }}>Return home</button></section></main>}
    {view === "settings" && <main className="flow-screen settings-screen"><AppHeader onHome={() => setView("home")} onSettings={() => setView("settings")} /><section className="settings-card"><div className="settings-heading"><div><p className="eyebrow">YOUR PREFERENCES</p><h1>Settings</h1></div><button className="icon-button" onClick={() => setView("home")}><X size={20} /></button></div><div className="setting-group"><h2>Practice style preference</h2>{practiceStyleOptions.map((style) => <button key={style.id} className={`setting-choice ${settingsStyle === style.id ? "selected" : ""}`} onClick={() => setSettingsStyle(style.id)}><span><b>{style.label}</b><small>{style.note}</small></span><i>{settingsStyle === style.id && <Check size={16} />}</i></button>)}</div><div className="setting-group"><h2>Accessibility</h2><label className="switch-row"><span><b>Reduced motion</b><small>Keep transitions subtle and still.</small></span><input checked={reducedMotion} onChange={(event) => setReducedMotion(event.target.checked)} type="checkbox" /><i /></label><div className="text-size-row"><span><b>Text size</b><small>Choose a comfortable reading size.</small></span><div className="segmented"><button className={textSize === "standard" ? "active" : ""} onClick={() => setTextSize("standard")}>A</button><button className={textSize === "large" ? "active" : ""} onClick={() => setTextSize("large")}>A+</button></div></div></div><div className="setting-group future-state"><p className="eyebrow">COMING SOON</p><h2>Recent practices &amp; favorites</h2><p>Your practice history and saved favorites will appear here in a future update.</p></div><div className="wellness-note"><Sparkles size={19} /><p><b>Wellness &amp; safety</b>This app supports grounding and reflection. It does not diagnose, treat, or replace professional care.</p></div><button className="secondary-button secondary-button--wide" onClick={() => setView("home")}><HomeIcon size={17} /> Back to home</button></section></main>}
    {view === "recommendation" && <button className={`favorite-fab ${activePracticeIsFavorite ? "saved" : ""}`} onClick={toggleActiveFavorite} aria-label={activePracticeIsFavorite ? "Remove this practice from favorites" : "Save this practice to favorites"}><Heart size={17} fill={activePracticeIsFavorite ? "currentColor" : "none"} /><span>{activePracticeIsFavorite ? "Saved" : "Save practice"}</span></button>}
    {view !== "onboarding" && <button className="library-fab" onClick={() => setView("library")} aria-label="Open your practice library"><Heart size={17} /><span>Your Library</span></button>}
    {view !== "onboarding" && <button className="quick-reset-fab" onClick={beginQuickReset} aria-label="Open a one-minute quick reset"><Bolt size={17} /><span>Need a Quick Reset?</span></button>}
    {view === "library" && isAuthenticated && <section className="library-enhancements"><div className="library-enhancements-card">{commitment && <button className="library-intention-shortcut" onClick={() => beginSavedPractice(commitment.practiceId)}><span className="library-intention-mark"><RotateCcw size={17} /></span><span><p className="eyebrow">CONTINUE YOUR SEVEN-DAY INTENTION</p><b>{commitment.practiceName}</b><small>{remainingCommitmentDays(commitment)} {remainingCommitmentDays(commitment) === 1 ? "day" : "days"} remaining</small></span><ArrowRight size={18} /></button>}<section className="library-refinement"><div className="library-section-heading"><div><p className="eyebrow">REFINE FAVORITES</p><h2>Find a saved meditation</h2></div><span>{filteredFavorites.length}</span></div><div className="library-filter-row"><label>Pathway<select value={favoritePathwayFilter} onChange={(event) => setFavoritePathwayFilter(event.target.value as FlowCategory | "all")}><option value="all">All pathways</option>{supportFlows.filter((item) => item.showOnDashboard).map((item) => <option key={item.id} value={item.id}>{item.dashboardLabel}</option>)}</select></label><label>Rose Ray<select value={favoriteRoseRayFilter} onChange={(event) => setFavoriteRoseRayFilter(event.target.value as RoseRayId | "all")}><option value="all">All Rose Rays</option>{Object.values(roseRays).map((ray) => <option key={ray.id} value={ray.id}>{ray.name}</option>)}</select></label></div>{filteredFavorites.length ? <div className="library-list library-list--filtered">{filteredFavorites.map(({ favorite, practice }) => <article className="library-item" key={favorite.id}><div className="library-item-mark"><Heart size={16} fill="currentColor" /></div><div><b>{practice.displayName}</b><small>{practice.flowCategory.map((flowId) => getFlow(flowId)?.dashboardLabel).filter(Boolean).join(" · ")}{practice.roseRayId ? ` · ${roseRays[practice.roseRayId].name}` : ""}</small></div><button onClick={() => beginSavedPractice(practice.id)}>Begin <Play size={14} fill="currentColor" /></button></article>)}</div> : <div className="library-empty"><Compass size={20} /><p><b>No saved practice matches these filters</b><span>Try a different pathway or Rose Ray to see more of your saved support.</span></p></div>}</section><section className="library-notes"><div className="library-section-heading"><div><p className="eyebrow">PRIVATE REFLECTIONS</p><h2>Add a note to a completed practice</h2></div></div>{practiceHistory.data?.length ? <div className="library-list">{practiceHistory.data.map((entry) => { const completed = practices.find((practice) => practice.id === entry.practiceId); return completed ? <article className="history-note-item" key={entry.id}><div><b>{completed.displayName}</b><small>Completed {new Date(entry.completedAt).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}</small>{editingHistoryNoteId === entry.id ? <><textarea value={historyNoteDraft} maxLength={1000} onChange={(event) => setHistoryNoteDraft(event.target.value)} placeholder="A private note for yourself…" rows={3} /><div className="note-actions"><button onClick={() => setEditingHistoryNoteId(null)}>Cancel</button><button className="note-save" disabled={updateHistoryNote.isPending} onClick={() => saveHistoryNote(entry.id)}>{updateHistoryNote.isPending ? "Saving…" : "Save note"}</button></div></> : <><p className={entry.note ? "history-note-copy" : "history-note-copy history-note-copy--empty"}>{entry.note || "No private note yet."}</p><button className="history-note-trigger" onClick={() => openHistoryNote(entry.id, entry.note)}>{entry.note ? "Edit note" : "Add a note"}</button></>}</div></article> : null; })}</div> : <div className="library-empty"><Clock3 size={20} /><p><b>Complete a practice first</b><span>Your private reflections can be attached to completed practices here.</span></p></div>}</section></div></section>}
    {view === "library" && isAuthenticated && <section className="saved-support-command"><div className="saved-support-command__card">{commitment && <button className="library-intention-shortcut" onClick={() => beginSavedPractice(commitment.practiceId)}><span className="library-intention-mark"><RotateCcw size={17} /></span><span><p className="eyebrow">CONTINUE YOUR SEVEN-DAY INTENTION</p><b>{commitment.practiceName}</b><small>{remainingCommitmentDays(commitment)} {remainingCommitmentDays(commitment) === 1 ? "day" : "days"} remaining</small></span><ArrowRight size={18} /></button>}<section className="saved-support-panel"><div className="library-section-heading"><div><p className="eyebrow">SEARCH &amp; FILTER</p><h2>Find a saved meditation</h2></div><span>{filteredFavorites.length}</span></div><input className="saved-support-search" value={favoriteKeyword} onChange={(event) => setFavoriteKeyword(event.target.value)} placeholder="Search saved meditations…" aria-label="Search saved meditations" /><div className="library-filter-row"><label>Pathway<select value={favoritePathwayFilter} onChange={(event) => setFavoritePathwayFilter(event.target.value as FlowCategory | "all")}><option value="all">All pathways</option>{supportFlows.filter((item) => item.showOnDashboard).map((item) => <option key={item.id} value={item.id}>{item.dashboardLabel}</option>)}</select></label><label>Rose Ray<select value={favoriteRoseRayFilter} onChange={(event) => setFavoriteRoseRayFilter(event.target.value as RoseRayId | "all")}><option value="all">All Rose Rays</option>{Object.values(roseRays).map((ray) => <option key={ray.id} value={ray.id}>{ray.name}</option>)}</select></label></div>{filteredFavorites.length ? <div className="library-list library-list--filtered">{filteredFavorites.map(({ favorite, practice }) => <article className="library-item" key={favorite.id}><div className="library-item-mark"><Heart size={16} fill="currentColor" /></div><div><b>{practice.displayName}</b><small>{practice.flowCategory.map((flowId) => getFlow(flowId)?.dashboardLabel).filter(Boolean).join(" · ")}{practice.roseRayId ? ` · ${roseRays[practice.roseRayId].name}` : ""}</small></div><div className="saved-item-actions"><button className={dailyDefault.data === practice.id ? "daily-default-active" : ""} onClick={() => selectDailyDefault(dailyDefault.data === practice.id ? null : practice.id)}>{dailyDefault.data === practice.id ? "Daily default" : "Set daily"}</button><button onClick={() => beginSavedPractice(practice.id)}>Begin <Play size={14} fill="currentColor" /></button></div></article>)}</div> : <div className="library-empty"><Compass size={20} /><p><b>No saved practice matches</b><span>Try another keyword, pathway, or Rose Ray.</span></p></div>}</section><section className="saved-support-panel saved-support-panel--notes"><div className="library-section-heading"><div><p className="eyebrow">PRIVATE REFLECTIONS</p><h2>Practice notes</h2></div><button className="note-export" onClick={exportHistoryNotes}>Export notes</button></div>{practiceHistory.data?.length ? <div className="library-list">{practiceHistory.data.map((entry) => { const completed = practices.find((practice) => practice.id === entry.practiceId); return completed ? <article className="history-note-item" key={entry.id}><div><b>{completed.displayName}</b><small>Completed {new Date(entry.completedAt).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}</small>{editingHistoryNoteId === entry.id ? <><textarea value={historyNoteDraft} maxLength={1000} onChange={(event) => setHistoryNoteDraft(event.target.value)} placeholder="A private note for yourself…" rows={3} /><div className="note-actions"><button onClick={() => setEditingHistoryNoteId(null)}>Cancel</button><button className="note-save" disabled={updateHistoryNote.isPending} onClick={() => saveHistoryNote(entry.id)}>{updateHistoryNote.isPending ? "Saving…" : "Save note"}</button></div></> : <><p className={entry.note ? "history-note-copy" : "history-note-copy history-note-copy--empty"}>{entry.note || "No private note yet."}</p><div className="history-note-controls"><button className="history-note-trigger" onClick={() => openHistoryNote(entry.id, entry.note)}>{entry.note ? "Edit note" : "Add a note"}</button>{entry.note && <button className="history-note-delete" onClick={() => deleteHistoryNote(entry.id)}>Delete note</button>}</div></>}</div></article> : null; })}</div> : <div className="library-empty"><Clock3 size={20} /><p><b>Complete a practice first</b><span>Your private reflections can be attached to completed practices here.</span></p></div>}</section></div></section>}
    {view === "library" && isAuthenticated && <PracticeHistoryTools />}
  </div>;
}
